interface LoginScreenProps {
  onSignIn: () => void;
}

export function LoginScreen({ onSignIn }: LoginScreenProps) {
  const [introComplete, setIntroComplete] = useState(false);

  return (
    <motion.div
      className="fixed inset-0 z-50 flex items-center justify-center"
      style={{
        backgroundColor: '#F5EFE6',
        backgroundImage: 'url(/login-bg.jpg)',
        backgroundSize: 'cover',
        backgroundPosition: 'center',
      }}
      initial={{ opacity: 1 }}
      animate={{ opacity: 1 }}
      exit={{ opacity: 0 }}
      transition={{ duration: 0.4 }}
    >
      {/* Login intro animation — sits above background, card hidden until complete */}
      {!introComplete && (
        <LoginIntroAnimation onComplete={() => setIntroComplete(true)} />
      )}

      {/* Floating card — only appears after intro finishes */}
      <AnimatePresence>
      {introComplete && (
      <motion.div
        className="w-full max-w-[400px] mx-6 rounded-2xl overflow-hidden"
        initial={{ opacity: 0, y: 16, scale: 0.98 }}
        animate={{ opacity: 1, y: 0, scale: 1 }}
        transition={{ duration: 0.45, ease: [0.16, 1, 0.3, 1] }}
        style={{
          /* Frost 60 → blur(14px), Refraction 100 → saturate(200%) */
          backdropFilter: 'blur(14px) saturate(100%) brightness(1.02)',
          WebkitBackdropFilter: 'blur(14px) saturate(100%) brightness(1.02)',

          /* Base tint + Light -45° (Figma -45° = CSS 315deg), intensity 80%, Splay 100 = full spread */
          background: [
            'linear-gradient(315deg, transparent 0%, rgba(255,255,255,0.04) 100%)',
            'rgba(255, 255, 255, 0.01)',
          ].join(', '),

          /* Fallback for no backdrop-filter support */
          backgroundColor: 'rgba(255, 255, 255, 0.35)',

          /* Depth 20 → subtle inset edge bevels (top bright, bottom dark, left soft) */
          boxShadow: [
            'inset 0 1px 0 rgba(255,255,255,0.55)',       /* top highlight – depth */
            'inset 1px 0 0 rgba(255,255,255,0.22)',        /* left edge – depth */
            'inset 0 -1px 0 rgba(0,0,0,0.05)',             /* bottom shadow – depth */
            /* Dispersion 50 – optional chromatic micro-halos; remove if too subtle */
            '0 0 0 0.5px rgba(241,93,34,0.12)',            /* warm (orange) fringe */
            '-0.5px 0 0 0.5px rgba(80,120,255,0.07)',      /* cool (blue) fringe */
            /* Drop shadow */
            '0 20px 56px rgba(10,10,10,0.13)',
          ].join(', '),

          border: '1px solid rgba(255,255,255,0.42)',
        }}
      >
        {/* Card header: OA logo SVG (IQ mark + divider + OneAdvanced) */}
        <div
          className="flex items-center px-6 py-4 mt-4"
          style={{ borderBottom: '1px solid rgba(255,255,255,0.3)' }}
        >
          <OALogo />
        </div>

        {/* log in header SVG: flame brandmark + "Welcome to IQ" + subtitle */}
        <div className="px-8 pt-14 pb-2">
          <LoginHeaderSVG />
        </div>

        {/* Form */}
        <div className="px-8 pt-5 pb-14 flex flex-col gap-4">

          {/* Email */}
          <div className="flex flex-col gap-1.5">
            <label className="text-sm font-medium" style={{ color: '#0A0A0A' }}>Email</label>
            <input
              type="email"
              className="w-full rounded px-4 py-3 text-sm outline-none border border-border"
              style={{ background: 'rgba(255,255,255,0.48)', color: '#1a1612' }}
            />
          </div>

          {/* Password */}
          <div className="flex flex-col gap-1.5">
            <label className="text-sm font-medium" style={{ color: '#0A0A0A' }}>Password</label>
            <input
              type="password"
              className="w-full rounded px-4 py-3 text-sm outline-none border border-border"
              style={{ background: 'rgba(255,255,255,0.48)', color: '#1a1612' }}
            />
          </div>

          {/* Sign in button */}
          <motion.button
            onClick={onSignIn}
            className="w-full flex items-center justify-center gap-2.5 rounded-xl py-3.5 text-sm font-semibold mt-4"
            style={{ background: '#3d3b35', color: '#FEFCF8' }}
            whileHover={{ scale: 1.01 }}
            whileTap={{ scale: 0.98 }}
            transition={{ duration: 0.15 }}
          >
            <ArrowRightIcon />
            <span>Sign in</span>
          </motion.button>

          {/* Forgot password */}
          <div className="flex justify-center">
            <button
              className="text-sm underline underline-offset-2 transition-opacity hover:opacity-60"
              style={{ color: '#484135' }}
            >
              Forgot password?
            </button>
          </div>

          {/* Or continue with */}
          <div className="flex items-center gap-3">
            <div className="flex-1 h-px" style={{ background: 'rgba(255,255,255,0.4)' }} />
            <span className="text-xs font-medium" style={{ color: 'rgba(80,70,55,0.8)' }}>Or continue with</span>
            <div className="flex-1 h-px" style={{ background: 'rgba(255,255,255,0.4)' }} />
          </div>

          {/* Social buttons */}
          <div className="flex gap-3">
            <button
              className="flex-1 flex items-center justify-center gap-2 rounded-xl py-3 text-sm font-medium hover:bg-black/5 transition-colors"
              style={{ background: 'rgba(255,255,255,0.48)', border: '1px solid rgba(255,255,255,0.5)', color: '#1a1612' }}
            >
              <LinkedInIcon />
              LinkedIn
            </button>
            <button
              className="flex-1 flex items-center justify-center gap-2 rounded-xl py-3 text-sm font-medium hover:bg-black/5 transition-colors"
              style={{ background: 'rgba(255,255,255,0.48)', border: '1px solid rgba(255,255,255,0.5)', color: '#1a1612' }}
            >
              <MicrosoftIcon />
              Microsoft
            </button>
          </div>

        </div>
      </motion.div>
      )}
      </AnimatePresence>
    </motion.div>
  );
}
